"""Auto-generated MCP tool definitions — DO NOT EDIT BY HAND.

Generated by scripts/generate_mcp_tools.py from:
- agent-workers/agents/domain_registry.py (domain agent actions)
- scripts/connector_tool_keys.txt        (platform tool registry)

Imported at the bottom of mcp_server.py so the @mcp.tool decorators
register against the same FastMCP instance as the hand-written tools.

To regenerate:
    python3 scripts/generate_mcp_tools.py

Namespace filtering (introduced in 0.6.0):
    Setting LIGHTBULB_MCP_NAMESPACES=finance,crm,gmail (comma-separated)
    restricts the *generated* tools to only those matching one of the listed
    prefixes. Hand-written tools in mcp_server.py are always registered.

    Unset / empty string → all generated tools register (current behaviour).

    Why: large generated surfaces can spend substantial tokens
    on tools/list per Claude Code session before the LLM does anything.
    Most customers only need a handful of integrations; filtering cuts the
    cold-start payload by ~80%.
"""

from __future__ import annotations

import json
import os
import sys
from typing import Literal, Optional

from mcp.types import ToolAnnotations
from lightbulb.mcp_server import (
    _get_client,
    _format_result,
    _call_with_retry,
    _maybe_route_generated_connector_invoke,
    _maybe_route_generated_domain_dispatch,
    _tool_registry,
    mcp,
)
from lightbulb.governed_connector_contracts import (
    EPHEMERAL_READ_IDEMPOTENCY_ERROR,
    is_ephemeral_non_replayable_read,
    reject_ephemeral_read_idempotency,
)


def _load_allowed_namespaces() -> set[str] | None:
    """Parse LIGHTBULB_MCP_NAMESPACES once at module import.

    Returns:
        ``None`` → no filtering (every generated tool registers).
        ``set[str]`` → only tools whose first underscore-segment is in this set.
    """
    raw = os.environ.get("LIGHTBULB_MCP_NAMESPACES", "").strip()
    if not raw:
        return None
    namespaces = {part.strip().lower() for part in raw.split(",") if part.strip()}
    return namespaces or None


_ALLOWED_NAMESPACES: set[str] | None = _load_allowed_namespaces()
REGISTERED_GENERATED_TOOL_NAMES: set[str] = set()
if _ALLOWED_NAMESPACES is not None:
    print(
        f"lightbulb-mcp: namespace filter active — generated tools restricted "
        f"to {sorted(_ALLOWED_NAMESPACES)} (hand-written tools always register)",
        file=sys.stderr,
    )


def _guarded_dispatch(domain: str, action: str, message: str, inputs: dict | None = None):
    routed = _maybe_route_generated_domain_dispatch(domain, action, message, inputs)
    if routed is not None:
        return routed
    return _get_client().dispatch(domain, action=action, message=message, inputs=inputs)


def _guarded_invoke_tool(
    tool_name: str,
    arguments: dict,
    *,
    project_id: str | None,
    project_ref: str | None,
    connector_account_ref: str | None,
    idempotency_key: str | None,
    effect: str | None,
    approval_ref: str | None,
):
    routed = _maybe_route_generated_connector_invoke(tool_name, arguments)
    if routed is not None:
        try:
            return json.loads(routed)
        except json.JSONDecodeError:
            return {"reply": routed}
    if tool_name == "gmail.send_email":
        threaded = arguments.get("thread_id") is not None
        parent_bound = arguments.get("parent_message_id") is not None
        if threaded != parent_bound:
            return {
                "schema": "lightbulb.mcp.connector_arguments_rejected.v1",
                "status": "blocked",
                "error": "connector_arguments_invalid",
                "tool": tool_name,
                "message": (
                    "Gmail threaded sends require both thread_id and "
                    "parent_message_id."
                ),
            }
    ephemeral_read = is_ephemeral_non_replayable_read(tool_name)
    try:
        reject_ephemeral_read_idempotency(tool_name, idempotency_key)
    except ValueError as exc:
        return {
            "schema": "lightbulb.mcp.ephemeral_read_idempotency_rejected.v1",
            "status": "blocked",
            "error": EPHEMERAL_READ_IDEMPOTENCY_ERROR,
            "tool": tool_name,
            "message": str(exc),
        }
    governance = {
        "project_id": project_id,
        "project_ref": project_ref,
        "connector_account_ref": connector_account_ref,
        "effect": effect,
    }
    if not ephemeral_read:
        governance["idempotency_key"] = idempotency_key
    missing = sorted(key for key, value in governance.items() if not value)
    if missing:
        return {
            "schema": "lightbulb.mcp.governed_connector_context_required.v1",
            "status": "blocked",
            "error": "governed_connector_context_required",
            "tool": tool_name,
            "missing": missing,
            "message": (
                "Direct connector operations require exact project/account custody, "
                + (
                    "and a server-verified read effect; this private-row read "
                    "intentionally omits idempotency."
                    if ephemeral_read
                    else "a stable idempotency key, and a server-verified effect."
                )
            ),
        }
    invoke_kwargs = {
        "project_id": project_id,
        "project_ref": project_ref,
        "connector_account_ref": connector_account_ref,
        "effect": effect,
        "approval_ref": approval_ref,
    }
    if not ephemeral_read:
        invoke_kwargs["idempotency_key"] = idempotency_key
    return _get_client().invoke_tool(tool_name, arguments, **invoke_kwargs)


def _ns_tool(
    namespace: str,
    *,
    capability_ref: str,
    effect_class: str,
    approval_required: bool = True,
    idempotency_required: bool = False,
):
    """Conditional ``@mcp.tool()`` decorator scoped to a known namespace.

    Each generated tool declares its namespace explicitly at codegen time
    (e.g. ``finance``, ``it_ops``, ``document_intelligence``, ``clio``,
    ``microsoft``) so multi-word names work without underscore-split
    ambiguity. Registers with FastMCP only when LIGHTBULB_MCP_NAMESPACES is
    unset OR the namespace is in the allow list. Skipped tools become a
    regular Python function (no MCP exposure) but stay importable.
    """
    read_only = effect_class == "read"
    annotations = ToolAnnotations(
        readOnlyHint=read_only,
        destructiveHint=not read_only,
        idempotentHint=idempotency_required,
        openWorldHint=True,
    )
    meta = {
        "lightbulb/capabilityRef": capability_ref,
        "lightbulb/effectClass": effect_class,
        "lightbulb/approvalRequired": approval_required,
        "lightbulb/idempotencyRequired": idempotency_required,
        "lightbulb/availability": "advanced_private",
        "lightbulb/certificationState": "UNCERTIFIED",
    }

    def decorator(fn):
        if _ALLOWED_NAMESPACES is None or namespace.lower() in _ALLOWED_NAMESPACES:
            registry = _tool_registry()
            tool_name = fn.__name__
            if tool_name in registry:
                raise RuntimeError(
                    f"Generated MCP tool name collision: {tool_name!r} is already registered"
                )
            registered = mcp.tool(annotations=annotations, meta=meta)(fn)
            if tool_name not in registry:
                raise RuntimeError(
                    f"Generated MCP tool {tool_name!r} did not register with FastMCP"
                )
            REGISTERED_GENERATED_TOOL_NAMES.add(tool_name)
            return registered
        return fn
    return decorator
# === Domain agent actions (605) ===

@_ns_tool('brain', capability_ref='brain.ask', effect_class='action')
def brain_ask(message: str = "", inputs: str = "{}") -> str:
    """Run the brain domain agent action `ask`.

    Routes through the platform's domain-agent dispatcher under your JWT,
    tenant, and company scope.

    Args:
        message: Free-text objective for the action.
        inputs: Optional JSON string of structured inputs for the action.
    """
    parsed_inputs = {}
    if inputs and inputs.strip() != "{}":
        try:
            parsed_inputs = json.loads(inputs)
        except json.JSONDecodeError:
            return f"Error: 'inputs' must be valid JSON, got: {inputs[:200]}"

    def _do():
        return _guarded_dispatch('brain', action='ask', message=message, inputs=parsed_inputs or None)
    return _format_result(_call_with_retry(_do))

