@_ns_tool('finance', capability_ref='finance.finance_stripe_ledger_reconciliation', effect_class='action')
def finance_stripe_ledger_reconciliation(message: str = "", month: Optional[str] = None, statement_url: Optional[str] = None, materiality_threshold_usd: Optional[float] = None) -> str:
    """Reconcile Stripe payment activity against your accounting ledger.

Surfaces missing entries, amount mismatches, and timing variances
between Stripe payouts and your bookkeeping. Outputs a reconciliation
summary plus an itemised exceptions list.
    Args:
        message: Free-text objective for the action.
        month: Period to reconcile (YYYY-MM).
        statement_url: Optional bank/ledger statement URL to tie out against.
        materiality_threshold_usd: Skip differences smaller than this threshold.
    """
    inputs: dict = {}
    if month is not None:
        inputs['month'] = month
    if statement_url is not None:
        inputs['statement_url'] = statement_url
    if materiality_threshold_usd is not None:
        inputs['materiality_threshold_usd'] = materiality_threshold_usd

    def _do():
        return _guarded_dispatch('finance', action='finance_stripe_ledger_reconciliation', message=message, inputs=inputs or None)
    return _format_result(_call_with_retry(_do))

