@_ns_tool(
    'shopify',
    capability_ref='shopify.update_menu',
    effect_class='write',
    approval_required=True,
    idempotency_required=True,
)
def shopify_update_menu(menu_id: Optional[str] = None, title: Optional[str] = None, handle: Optional[str] = None, items: Optional[list[str]] = None, expected_preimage_sha256: Optional[str] = None, *, project_id: Optional[str] = None, project_ref: Optional[str] = None, connector_account_ref: Optional[str] = None, idempotency_key: Optional[str] = None, effect: Optional[str] = None, approval_ref: Optional[str] = None) -> str:
    """Replace a storefront navigation menu's title, handle, and full item tree.
This is a whole-menu replacement — read the menu first with
shopify.get_menu, approve its exact semantic preimage, and send back every
item you want to keep. The connector re-reads the preimage immediately before
dispatch and independently compares the complete result. Requires the
online-store-navigation scopes; a connection without them returns
SHOPIFY_NAVIGATION_SCOPE_REQUIRED (offer a Shopify reconnect).

    Args:
        menu_id (required): Menu ID to update (numeric or GID).
        title (required): Menu title (send the existing title to keep it).
        handle (required): Menu handle (send the existing handle to keep it).
        items (required): JSON-string list of the menu's complete item tree: [{title, type?, url?, resource_id?, items?}]. Items omitted here are removed from the menu.
        expected_preimage_sha256 (required): Exact governed get_menu semantic-tree digest approved for replacement. A changed digest fails before provider dispatch.
        project_id: Authenticated Project UUID.
        project_ref: Exact project correlation reference.
        connector_account_ref: Project-bound connector account alias.
        idempotency_key: Stable business-action identity.
        effect: Claimed read or write effect; Spring verifies it.
        approval_ref: Approved platform task UUID when resuming a write.
    """
    arguments: dict = {}
    if menu_id is not None:
        arguments['menu_id'] = menu_id
    if title is not None:
        arguments['title'] = title
    if handle is not None:
        arguments['handle'] = handle
    if items is not None:
        arguments['items'] = items
    if expected_preimage_sha256 is not None:
        arguments['expected_preimage_sha256'] = expected_preimage_sha256

    def _do():
        return _guarded_invoke_tool(
            'shopify.update_menu',
            arguments,
            project_id=project_id,
            project_ref=project_ref,
            connector_account_ref=connector_account_ref,
            idempotency_key=idempotency_key,
            effect=effect,
            approval_ref=approval_ref,
        )
    result = _do()
    return json.dumps(result, indent=2, default=str)[:5000]

